# AURA SYNAPSE V9.4 FINAL APROBADO - VECTOR FLOW TERMINAL - DECISION SOCIOS SYNA & YESID
import os, time, threading
from datetime import datetime
import pytz
from flask import Flask, render_template_string, jsonify
import yfinance as yf
import requests
from alpaca.trading.client import TradingClient
from alpaca.trading.requests import MarketOrderRequest, TrailingStopOrderRequest, GetOrdersRequest
from alpaca.trading.enums import OrderSide, TimeInForce, QueryOrderStatus

app = Flask(__name__)

ALPACA_KEY = os.getenv("ALPACA_API_KEY")
ALPACA_SECRET = os.getenv("ALPACA_SECRET_KEY")
ALPACA_PAPER = True
TELEGRAM_TOKEN = os.getenv("TELEGRAM_TOKEN")
TELEGRAM_CHAT = os.getenv("TELEGRAM_CHAT_ID")

SYMBOLS = ["SPY", "QQQ", "AAPL", "MSFT", "NVDA", "TSLA"]
TRAILING_CONFIG = {
    "SPY": {"buy": 0.5, "sell": 2.0, "qty": 10},
    "QQQ": {"buy": 0.75, "sell": 2.5, "qty": 5},
    "AAPL": {"buy": 1.0, "sell": 3.0, "qty": 10},
    "MSFT": {"buy": 1.0, "sell": 3.0, "qty": 5},
    "NVDA": {"buy": 1.5, "sell": 4.0, "qty": 10},
    "TSLA": {"buy": 1.5, "sell": 4.0, "qty": 5},
}
RSI_BUY = 35

NY_TZ = pytz.timezone('America/New_York')
BOGOTA_TZ = pytz.timezone('America/Bogota')
trading_client = TradingClient(ALPACA_KEY, ALPACA_SECRET, paper=ALPACA_PAPER)

LOGO_B64 = ""
STATE = {"equity": 100558.85, "cash": 68197.15, "positions": {}, "logs": ["[18:25:00 BOG] SYNC REAL: 5 pos", "[18:25:00 BOG] V9.4 FINAL APROBADO - VECTOR FLOW"], "last_run": None, "flat_done_today": False, "trailing_active": {}, "rsi_data": {}, "buying_power": 347209, "reclass": {}}

def send_telegram(msg):
    if not TELEGRAM_TOKEN or not TELEGRAM_CHAT: return
    try: requests.post(f"https://api.telegram.org/bot{TELEGRAM_TOKEN}/sendMessage", data={"chat_id": TELEGRAM_CHAT, "text": f"AURA V9.4: {msg}"}, timeout=5)
    except: pass

def log(msg):
    ts = datetime.now(BOGOTA_TZ).strftime("%H:%M:%S")
    STATE["logs"].insert(0, f"[{ts} BOG] {msg}")
    STATE["logs"] = STATE["logs"][:100]

def sync_alpaca_positions():
    try:
        alpaca_positions = trading_client.get_all_positions()
        STATE["positions"].clear()
        for p in alpaca_positions:
            STATE["positions"][p.symbol] = {
                "qty": float(p.qty),
                "entry_price": float(p.avg_entry_price),
                "market_value": float(p.market_value),
                "pl": float(p.unrealized_pl),
                "plpc": float(p.unrealized_plpc)*100
            }
        log(f"SYNC REAL: {len(alpaca_positions)} pos")
        return True
    except Exception as e:
        log(f"Error sync: {e}")
        return False

def get_rsi(symbol):
    try:
        df = yf.download(symbol, period="2d", interval="15m", progress=False)
        if len(df) < 14:
            df = yf.download(symbol, period="5d", interval="1d", progress=False)
            if len(df) < 14: return None
        delta = df['Close'].diff()
        gain = (delta.where(delta > 0, 0)).rolling(14).mean()
        loss = (-delta.where(delta < 0, 0)).rolling(14).mean()
        rsi = 100 - (100 / (1 + (gain/loss)))
        return float(rsi.iloc[-1]), float(df['Close'].iloc[-1]), df
    except: return None

def get_open_orders(symbol=None):
    try:
        req = GetOrdersRequest(status=QueryOrderStatus.OPEN)
        orders = trading_client.get_orders(filter=req)
        if symbol: return [o for o in orders if o.symbol == symbol]
        return orders
    except: return []

def is_market_open():
    now = datetime.now(NY_TZ)
    if now.weekday() >= 5: return False
    return (now.hour > 9 or (now.hour == 9 and now.minute >= 30)) and now.hour < 16

def analizar_desempeno_orden(symbol, entry_price, current_price, rsi_actual, df_5m):
    try:
        pl_pct = ((current_price - entry_price) / entry_price) * 100
        if df_5m is not None and len(df_5m) >= 3:
            mom_5m = ((df_5m['Close'].iloc[-1] - df_5m['Close'].iloc[-3]) / df_5m['Close'].iloc[-3]) * 100
        else: mom_5m = 0
        if pl_pct >= 1.5 and mom_5m > 0.3 and rsi_actual < 68: return "FUERTE", 1.2, f"FUERTE PL {pl_pct:+.1f}% Mom {mom_5m:+.1f}%", pl_pct, mom_5m
        elif pl_pct >= 0.5 and mom_5m > 0: return "NEUTRO_ALCISTA", 2.0, f"NEUTRO PL {pl_pct:+.1f}%", pl_pct, mom_5m
        elif pl_pct < -0.8: return "DEBIL", 4.5, f"DEBIL PL {pl_pct:+.1f}%", pl_pct, mom_5m
        else: return "NEUTRO", 2.8, f"NEUTRO PL {pl_pct:+.1f}%", pl_pct, mom_5m
    except: return "ERROR", 3.0, "Error", 0, 0

def check_eod_flat_real():
    now = datetime.now(NY_TZ)
    if now.hour == 15 and now.minute >= 45 and not STATE["flat_done_today"]:
        sync_alpaca_positions()
        if len(STATE["positions"]) > 0:
            log(f"LOCK FLAT REAL 15:45 - {len(STATE['positions'])}")
            try: trading_client.cancel_orders(); time.sleep(1)
            except: pass
            for sym in list(STATE["positions"].keys()):
                try: trading_client.close_position(sym)
                except: pass
            STATE["flat_done_today"]=True
            time.sleep(2)
            sync_alpaca_positions()
            return True
    if now.hour == 9 and now.minute == 30: STATE["flat_done_today"]=False
    return False

def run_aura():
    try:
        acct=trading_client.get_account()
        STATE["equity"]=float(acct.equity)
        STATE["cash"]=float(acct.cash)
        STATE["buying_power"]=float(acct.buying_power)
    except: pass
    sync_alpaca_positions()
    for symbol in SYMBOLS:
        res=get_rsi(symbol)
        if not res: continue
        rsi, price, df = res
        STATE["rsi_data"][symbol] = {"rsi": rsi, "price": price, "df": df}
    STATE["last_run"]=datetime.now(BOGOTA_TZ).strftime("%Y-%m-%d %H:%M:%S BOG")
    if check_eod_flat_real(): return
    if not is_market_open():
        log("Mercado cerrado - Display sync + RSI")
        return
    log("--- V9.4 RE-CLASSIFIER SCAN ---")
    for symbol in SYMBOLS:
        if symbol not in STATE["rsi_data"]: continue
        rsi = STATE["rsi_data"][symbol]["rsi"]
        price = STATE["rsi_data"][symbol]["price"]
        df = STATE["rsi_data"][symbol]["df"]
        config=TRAILING_CONFIG[symbol]
        open_orders=get_open_orders(symbol)
        has_trailing=any(o.type=='trailing_stop' for o in open_orders)
        if rsi < RSI_BUY and symbol not in STATE["positions"] and not has_trailing:
            try:
                trading_client.submit_order(TrailingStopOrderRequest(symbol=symbol, qty=config["qty"], side=OrderSide.BUY, trail_percent=config["buy"], time_in_force=TimeInForce.DAY))
                log(f"COMPRA TRAIL {symbol} RSI {rsi:.1f}")
                STATE["trailing_active"][symbol]=f"BUY {config['buy']}%"
            except Exception as e: log(f"Error Buy {symbol}: {e}")
        if symbol in STATE["positions"]:
            entry=STATE["positions"][symbol]['entry_price']
            clasif, nuevo_trail, detalle, pl_pct, mom_5m = analizar_desempeno_orden(symbol, entry, price, rsi, df)
            STATE["reclass"][symbol] = {"clasif": clasif, "trail": nuevo_trail, "pl": pl_pct, "mom": mom_5m, "detalle": detalle}
            log(f"{symbol} {detalle}")
            if has_trailing:
                cur = STATE["trailing_active"].get(symbol, "")
                if clasif in ["FUERTE", "DEBIL"] and str(nuevo_trail) not in cur:
                    try:
                        for o in open_orders: trading_client.cancel_order_by_id(o.id)
                        time.sleep(0.5)
                        trading_client.submit_order(TrailingStopOrderRequest(symbol=symbol, qty=STATE["positions"][symbol]['qty'], side=OrderSide.SELL, trail_percent=nuevo_trail, time_in_force=TimeInForce.DAY))
                        STATE["trailing_active"][symbol]=f"SELL {nuevo_trail}% [{clasif}]"
                        log(f"RECLASIFICADO {symbol} -> {nuevo_trail}% [{clasif}]")
                    except Exception as e: log(f"Error reclas {symbol}: {e}")
            else:
                if pl_pct >= 0.5:
                    try:
                        trading_client.submit_order(TrailingStopOrderRequest(symbol=symbol, qty=STATE["positions"][symbol]['qty'], side=OrderSide.SELL, trail_percent=nuevo_trail, time_in_force=TimeInForce.DAY))
                        STATE["trailing_active"][symbol]=f"SELL {nuevo_trail}% [{clasif}]"
                    except: pass

